// ── Leer datos del Webhook ─────────────────────────────────────────────
const webhookBody = $('Webhook').first().json.body;
const userId               = webhookBody.user_id;
const availableIngredients = webhookBody.available_ingredients || [];
const mealTypeOverride     = webhookBody.meal_type_override   || null;

// ── Leer resultado de la query SQL ────────────────────────────────────
const sql = $input.first().json;

const caloriesGoal     = Number(sql.calories_goal);
const proteinsGoal     = Number(sql.proteins_goal);
const carbsGoal        = Number(sql.carbs_goal);
const fatsGoal         = Number(sql.fats_goal);
const caloriesConsumed = Number(sql.calories_consumed);
const proteinsConsumed = Number(sql.proteins_consumed);
const carbsConsumed    = Number(sql.carbs_consumed);
const fatsConsumed     = Number(sql.fats_consumed);
const goal             = sql.goal;
const weightKg         = Number(sql.weight_kg);

// ── Parsear tipos de comida consumidos ────────────────────────────────
let consumedTypes = [];
try {
  consumedTypes = typeof sql.consumed_meal_types === 'string'
    ? JSON.parse(sql.consumed_meal_types)
    : sql.consumed_meal_types || [];
} catch(e) {
  consumedTypes = [];
}

// ── Calcular macros restantes ─────────────────────────────────────────
const remainingCalories = Math.max(0, caloriesGoal - caloriesConsumed);
const remainingProteins = Math.max(0, proteinsGoal - proteinsConsumed);
const remainingCarbs    = Math.max(0, carbsGoal    - carbsConsumed);
const remainingFats     = Math.max(0, fatsGoal     - fatsConsumed);

// ── Inferir meal_type ─────────────────────────────────────────────────
function inferMealType(consumed, hour) {
  if (!consumed.includes('breakfast') && hour < 12)              return 'breakfast';
  if (!consumed.includes('lunch')     && hour >= 10 && hour < 17) return 'lunch';
  if (!consumed.includes('dinner')    && hour >= 15)             return 'dinner';
  const slots = ['breakfast', 'lunch', 'dinner', 'snack'];
  for (const s of slots) {
    if (!consumed.includes(s)) return s;
  }
  return 'snack';
}

const hour             = new Date().getHours();
const suggestedMealType = mealTypeOverride || inferMealType(consumedTypes, hour);

// ── Mapas de texto ────────────────────────────────────────────────────
const goalMap = {
  lose_weight:         'Perder peso',
  gain_muscle:         'Ganar músculo',
  maintain:            'Mantener peso',
  improve_performance: 'Mejorar rendimiento',
};
const mealTypeMap = {
  breakfast: 'Desayuno',
  lunch:     'Almuerzo',
  dinner:    'Cena',
  snack:     'Merienda',
};

const goalText     = goalMap[goal]                 || goal;
const mealTypeText = mealTypeMap[suggestedMealType] || suggestedMealType;

const ingredientsText = availableIngredients.length > 0
  ? availableIngredients.join(', ')
  : 'No se especificaron — sugiere ingredientes comunes y saludables';

const consumedText = consumedTypes.length > 0
  ? consumedTypes.map(t => mealTypeMap[t] || t).join(', ')
  : 'Ninguna aún';

// ── Construir prompt para el AI Agent ─────────────────────────────────
const prompt = `Objetivo del usuario: ${goalText}
Peso: ${weightKg} kg

Tipo de comida sugerida: ${mealTypeText} (${suggestedMealType})

Calorías restantes del día: ${remainingCalories.toFixed(0)} kcal
Macros restantes:
- Proteína: ${remainingProteins.toFixed(0)}g
- Carbohidratos: ${remainingCarbs.toFixed(0)}g
- Grasas: ${remainingFats.toFixed(0)}g

Ingredientes disponibles: ${ingredientsText}
Comidas ya registradas hoy: ${consumedText}

Genera UNA recomendación de comida para ${mealTypeText}.`;

return [{
  json: {
    prompt,
    suggested_meal_type: suggestedMealType,
    user_id:             userId,
    remaining_calories:  remainingCalories,
    remaining_proteins:  remainingProteins,
    remaining_carbs:     remainingCarbs,
    remaining_fats:      remainingFats,
  }
}];
